const CACHE = "sf-site-files";        // one cache, updated file by file
const META = "sf-site-meta";          // remembers which version of each file is saved
const SCOPE = self.registration.scope; // e.g. https://user.github.io/sandfly-identification/
const abs = (p) => new URL(p, SCOPE).href;
const META_URL = abs("__offline-meta.json");
const TOTAL = Object.keys(FILES).length;
let status = { type: "sf-offline", state: "idle", done: 0, total: TOTAL, version: VERSION };

async function tell(extra) {
  Object.assign(status, extra || {});
  const all = await self.clients.matchAll({ includeUncontrolled: true });
  all.forEach((c) => c.postMessage(status));
}
async function readMeta() {
  const r = await (await caches.open(META)).match(META_URL);
  return r ? r.json() : {};
}
async function writeMeta(m) {
  await (await caches.open(META)).put(META_URL, new Response(JSON.stringify(m), { headers: { "content-type": "application/json" } }));
}

async function sync() {
  const cache = await caches.open(CACHE);
  const saved = await readMeta();
  const now = {};
  const todo = [];
  const present = new Set((await cache.keys()).map((r) => r.url));
  for (const [p, h] of Object.entries(FILES)) (saved[p] === h && present.has(abs(p)) ? (now[p] = h) : todo.push([p, h]));
  await tell({ state: todo.length ? "saving" : "ready", done: TOTAL - todo.length });
  let next = 0, sinceMeta = 0;
  async function worker() {
    while (next < todo.length) {
      const [p, h] = todo[next++];
      try {
        const res = await fetch(abs(p), { cache: "reload" });
        if (res.ok) { await cache.put(abs(p), res); now[p] = h; }
      } catch (e) { /* offline or failed: retried on the next visit */ }
      status.done++;
      if (++sinceMeta >= 25) { sinceMeta = 0; await writeMeta(Object.assign({}, saved, now)); await tell(); }
    }
  }
  await Promise.all(Array.from({ length: 6 }, worker));
  for (const p of Object.keys(saved)) if (!(p in FILES)) await cache.delete(abs(p));  // files removed from the site
  await writeMeta(now);
  const have = Object.keys(now).length;
  await tell({ state: have === TOTAL ? "ready" : "partial", done: have });
}

let running = null;  // never run two downloads at once
function syncOnce() {
  if (!running) running = sync().catch(() => {}).then(() => { running = null; });
  return running;
}
self.addEventListener("install", (e) => { e.waitUntil(syncOnce().then(() => self.skipWaiting())); });
self.addEventListener("activate", (e) => { e.waitUntil(self.clients.claim().then(() => tell())); });
self.addEventListener("message", (e) => {
  if (e.data !== "sf-status") return;
  // self-healing: check the saved files (fills in anything missing), then report to every open page
  e.waitUntil(syncOnce().then(() => tell()));
});

// Saved copy first (works offline); fall back to the network for anything not saved yet.
self.addEventListener("fetch", (e) => {
  const req = e.request;
  if (req.method !== "GET") return;
  const url = new URL(req.url);
  if (!url.href.startsWith(SCOPE)) return;          // other websites (CDC, DOIs...) go to the network as usual
  e.respondWith((async () => {
    let key = url.origin + url.pathname;
    if (key.endsWith("/")) key += "index.html";      // folder address -> its index.html
    const cache = await caches.open(CACHE);
    const hit = await cache.match(key);
    if (hit) return hit;
    try {
      return await fetch(req);
    } catch (err) {
      if (req.mode === "navigate") {
        const home = await cache.match(abs("index.html"));
        if (home) return home;
      }
      return new Response("This page is not saved for offline use yet. Connect to the internet once and reload.",
        { status: 503, headers: { "content-type": "text/plain; charset=utf-8" } });
    }
  })());
});
